# idea: fine V1 Gabor energy with deep cortical-magnification fovea + random tower + 2nd-order scatter + Gram
"""
Untrained ventral encoder: fine V1 energy + structured 2nd-order scattering + a random tower.

Front-end: complex Gabor bank (8 orient x 2 freq) applied to luminance and two opponent-color
channels (grouped conv) -> 48 phase-invariant energy maps. Luminance energy is fine 9x9 pooled
(early retinotopy); chromatic energy coarse 5x5. A 3x3 local Gram of luminance energy adds texture.

2nd-order scattering: a coarse 8-orient Gabor applied depthwise to ALL 48 energy maps (modulus) =
curvature/contour co-occurrence across luminance AND color, globally pooled (ventral invariance).

Random tower: 3-block fixed-random conv stack on luminance energy + color, ReLU+square dual
nonlinearity (simple+complex cells), LRN, maxpool; deepest-layer Gram. All concat, D_out<10k,
untrained, per-sample.
"""
import math
import torch
import torch.nn.functional as F

SEED = 0


def _gabor_bank(ksize, orientations, freqs, gamma=0.6, device="cpu"):
    half = (ksize - 1) / 2.0
    ys, xs = torch.meshgrid(torch.arange(ksize, device=device) - half,
                            torch.arange(ksize, device=device) - half, indexing="ij")
    ev_k, od_k = [], []
    for th in orientations:
        ct, st = math.cos(th), math.sin(th); xr = xs * ct + ys * st; yr = -xs * st + ys * ct
        for lam in freqs:
            sig = 0.56 * lam
            env = torch.exp(-(xr ** 2 + (gamma ** 2) * yr ** 2) / (2 * sig ** 2))
            ev = env * torch.cos(2 * math.pi * xr / lam); od = env * torch.sin(2 * math.pi * xr / lam)
            ev_k.append(ev - ev.mean()); od_k.append(od - od.mean())
    return torch.stack(ev_k + od_k, 0).unsqueeze(1)


def _lrn(x, eps=1e-4):
    return x / torch.sqrt(x.pow(2).mean(1, keepdim=True) + eps)


def _endstop_bank(ksize, orientations, d, device="cpu"):
    # hypercomplex / end-stopped kernels: a positive centre lobe minus two negative lobes displaced
    # ALONG each orientation, so a continuing contour is suppressed but a line-ending / high-curvature
    # point responds (a V2/V4 mid-level form cue absent from pure energy/Gram features).
    half = (ksize - 1) / 2.0
    ys, xs = torch.meshgrid(torch.arange(ksize, device=device) - half,
                            torch.arange(ksize, device=device) - half, indexing="ij")
    ks = []
    for th in orientations:
        ct, st = math.cos(th), math.sin(th)
        c = torch.exp(-(xs ** 2 + ys ** 2) / 2.0)
        f1 = torch.exp(-(((xs - d * ct) ** 2 + (ys - d * st) ** 2)) / 2.0)
        f2 = torch.exp(-(((xs + d * ct) ** 2 + (ys + d * st) ** 2)) / 2.0)
        k = c - 0.5 * (f1 + f2)
        ks.append(k - k.mean())
    return torch.stack(ks, 0).unsqueeze(1)


def _divnorm(e, k=9, sig=0.5):
    # canonical cortical/LGN divisive normalization: each unit / pooled local energy
    p = torch.sqrt(F.avg_pool2d(e.sum(1, keepdim=True), k, 1, k // 2) + 1e-6)
    return e / (sig * p.mean(dim=(2, 3), keepdim=True).clamp_min(1e-4) + p)


def _gram(feat, grid, B):
    C = feat.shape[1]; iu, ju = torch.triu_indices(C, C, device=feat.device)
    return F.adaptive_avg_pool2d(feat[:, iu] * feat[:, ju], grid).reshape(B, -1)


def _gram_fov(feat, tiers, B):
    # foveal Gram: cross-channel products pooled with log-polar central tiers (full field + central
    # crop), so texture correlations carry coarse central-vs-global structure at fewer dims than a grid.
    C = feat.shape[1]; iu, ju = torch.triu_indices(C, C, device=feat.device)
    return _foveal(feat[:, iu] * feat[:, ju], tiers, B, p=1.0)


def _foveal(m, tiers, B, p=0.25):
    # cortical-magnification readout approximating log-polar density: a list of (crop_div, grid)
    # tiers. crop_div=1 is the full field; 2 the central half; 4 the central quarter (high-acuity
    # fovea). Each crop is pooled to its own grid and concatenated -> the centre is over-sampled.
    H = m.shape[-1]; outs = []
    for cd, g in tiers:
        if cd == 1:
            sub = m
        else:
            c = H // cd; lo = (H - c) // 2; sub = m[:, :, lo:lo + c, lo:lo + c]
        outs.append((F.adaptive_avg_pool2d(sub, g) + 1e-6).pow(p).reshape(B, -1))
    return torch.cat(outs, 1)


class Model:
    name = "tricolor-gabor-oriented-boundaries-tower"
    idea = "augment the ventral deep-texture Gram's input with downsampled Gabor energy so the covariance captures cross-domain energy x deep-feature binding (oriented texture related to high-level structure)"
    description = (
        "Untrained encoder: the deep-Gram champion, but before the wide random conv the deepest tower features "
        "(128ch) are concatenated with the downsampled oriented Gabor energy (20ch, avg-pooled to the deep "
        "resolution). The wide conv (->192ch) and the global magnitude-preserving covariance Gram thus include "
        "cross terms binding oriented ENERGY to high-level DEEP features -- how texture co-occurs with object "
        "structure -- which the tower-only Gram cannot form. Output width and all other blocks unchanged."
    )
    insight = (
        "Deep-feature covariance is the ventral lever and tower-only depth/width/projection are tapped out. Binding "
        "the high-level tower features to the structured Gabor energy in one covariance adds genuinely new cross-"
        "domain terms (energy x deep) absent from either the energy Grams or the tower Gram alone. If ventral rises, "
        "cross-domain feature binding is a fresh axis; if flat, the tower already internalizes the oriented-energy "
        "information and the cross terms are redundant."
    )

    def __init__(self):
        self.no = 10; self.k1 = 11; self.f1 = [2.5, 5.0]; self.np1 = 10 * 2
        self.tw = [32, 64, 128]
        self._gb = None; self._gb2 = None; self._sc2 = None; self._w = None
        self._rp2 = None; self._w5 = None
        self._built = False; self.n_params = 0

    def _build(self, dev):
        o1 = [i * math.pi / self.no for i in range(self.no)]
        bank = _gabor_bank(self.k1, o1, self.f1, device=dev)               # (32,1,k,k)
        self._gb = bank.repeat(3, 1, 1, 1)                                 # grouped over 3 channels
        ne = self.np1 * 3                                                  # 48
        self._gb2 = _gabor_bank(9, [i * math.pi / 8 for i in range(8)], [3.0, 5.0, 8.0], device=dev)  # 48
        self._sc2 = self._gb2.repeat(23, 1, 1, 1)   # global scatter on luminance + a little red-green (23ch; 4 channels traded for the deep symmetry block)
        # compact 2nd-order scatter bank (8 orient x 2 freq) for the luminance spatial scatter
        self._b2f = _gabor_bank(9, [i * math.pi / 8 for i in range(8)], [3.0, 5.0], device=dev)
        # extra coarse-frequency V1 bank (3rd scale of the frequency-matched retinotopic pyramid)
        self._flo = _gabor_bank(15, o1, [9.0], device=dev)
        self._es = _endstop_bank(9, o1, 3.0, device=dev)               # end-stop bank, one kernel per orient
        self._es5 = _endstop_bank(13, o1, 5.0, device=dev)             # larger-radius end-stop (coarser curvature)
        self._gbc = _gabor_bank(21, [i * math.pi / 8 for i in range(8)], [13.0], device=dev).repeat(3, 1, 1, 1)  # coarse ventral, 3ch
        g = torch.Generator(device=dev).manual_seed(SEED)
        self._w = []; prev = 3
        for i, c in enumerate(self.tw):
            k = 7 if i == 0 else 3
            self._w.append(torch.randn(c, prev, k, k, generator=g, device=dev) / math.sqrt(prev * k * k)); prev = c
        # extra WIDE random conv (128 -> 192) kept at the deepest resolution (no maxpool, no spatial
        # coarsening) to enrich the feature basis the deep Gram covaries over
        self._w5 = torch.randn(192, self.tw[2] + self.np1, 3, 3, generator=g, device=dev) / math.sqrt((self.tw[2] + self.np1) * 9)
        # fixed random projection for the deep Gram: wide deep features (192ch -> 24)
        self._rp2 = torch.randn(24, 192, 1, 1, generator=g, device=dev) / math.sqrt(192)
        self.n_params = int(bank.numel() + self._gb2.numel() + self._b2f.numel() + self._flo.numel() + self._es.numel() + self._es5.numel() + self._gbc.numel() + self._w5.numel() + self._rp2.numel() + sum(w.numel() for w in self._w))
        self._built = True

    @staticmethod
    def _gauss(k, sig, dev):
        a = torch.arange(k, device=dev) - (k - 1) / 2.0
        g = torch.exp(-(a[:, None] ** 2 + a[None, :] ** 2) / (2 * sig ** 2))
        return g / g.sum()

    def _energy(self, x3):
        K = self.np1
        resp = F.conv2d(x3, self._gb, padding=self.k1 // 2, groups=3)
        outs = [torch.sqrt(resp[:, c * 2 * K:c * 2 * K + K] ** 2 + resp[:, c * 2 * K + K:(c + 1) * 2 * K] ** 2 + 1e-6) for c in range(3)]
        return torch.cat(outs, 1)                                          # (B,48,H,W)

    def _scatter2(self, e):
        B, C, H, W = e.shape
        r = F.conv2d(e, self._sc2, padding=4, groups=C).reshape(B, C, 48, H, W)
        return torch.sqrt(r[:, :, :24] ** 2 + r[:, :, 24:] ** 2 + 1e-6).reshape(B, C * 24, H, W)

    def _scat(self, e, bank):
        B, C, H, W = e.shape; nf = bank.shape[0]; half = nf // 2
        r = F.conv2d(e, bank.repeat(C, 1, 1, 1), padding=bank.shape[-1] // 2, groups=C).reshape(B, C, nf, H, W)
        return torch.sqrt(r[:, :, :half] ** 2 + r[:, :, half:] ** 2 + 1e-6).reshape(B, C * half, H, W)

    def _en1(self, x, bank):
        resp = F.conv2d(x, bank, padding=bank.shape[-1] // 2); n = bank.shape[0] // 2
        return torch.sqrt(resp[:, :n] ** 2 + resp[:, n:] ** 2 + 1e-6)

    @torch.no_grad()
    def __call__(self, X):
        X = torch.as_tensor(X)
        if X.shape[0] > 64:
            return torch.cat([self.__call__(X[i:i + 64]) for i in range(0, X.shape[0], 64)], 0)
        dev = X.device
        if not self._built or self._gb.device != dev:
            self._build(dev)
        B = X.shape[0]; s = int(round(math.sqrt(X.shape[1] / 3)))
        img = X.reshape(B, s, s, 3).permute(0, 3, 1, 2).float()
        r, gc, b = img[:, 0:1], img[:, 1:2], img[:, 2:3]
        lum = 0.299 * r + 0.587 * gc + 0.114 * b; rg = r - gc; by = b - 0.5 * (r + gc)
        K = self.np1
        energy = self._energy(torch.cat([lum, rg, by], 1))                # (B,48,128,128)
        lum_e = energy[:, :K]; col_e = _divnorm(energy[:, K:]); lum_dn = _divnorm(lum_e)
        c1 = F.max_pool2d(lum_dn, 4, 4)
        c0 = F.max_pool2d(lum_dn, 2, 2)                                   # finer 64x64 luminance energy map
        # frequency-matched retinotopic V1 pyramid with FOVEAL (cortical-magnification) sampling:
        # each scale read as a coarse full-field grid + a denser central-crop grid, over-representing
        # the fovea like early visual cortex. fine freq finest, coarse freq sparsest.
        # foveal red-green opponent-colour energy map added to the early pyramid: center-dense chromatic
        # energy for foveal V1/V2/hV4 colour responses (combines the two validated levers: foveal + colour).
        feats = [_foveal(lum_e[:, ::2], [(1, 10), (2, 9), (4, 7), (8, 6)], B),
                 _foveal(lum_e[:, 1::2], [(1, 7), (2, 5), (4, 4)], B),
                 _gram(_lrn(c1[:, ::2]), 3, B),
                 _gram_fov(_lrn(c0), [(1, 1), (2, 1)], B)]
        # cross-scale frequency coupling per orientation (fine x coarse energy) -> scale-binding map,
        # then its 2nd-order SPATIAL scatter (8 orient x 2 freq modulus, pooled 2x2): how scale-bound
        # contour texture is laid out -- a strong mid/high-level ventral form code.
        xs = _lrn(c1[:, ::2]) * _lrn(c1[:, 1::2])
        feats.append(torch.sqrt(F.adaptive_avg_pool2d(self._scat(xs, self._b2f), 2)+1e-6).reshape(B, -1))
        # (end-stopping block removed -- its foveal budget is reinvested in deeper cortical-magnification
        # tiers (8x,16x central crops) of the proven fine V1 pyramid above, testing edge-curvature value)
        # BILATERAL-SYMMETRY energy: oriented V1 energy multiplied by its left-right mirror about the vertical
        # midline -> high where the pattern is vertically symmetric (faces, centred objects), read foveally.
        # A face/object-centering cue targeting the weak FFA/ventral voxels; bounded, per-image, additive.
        # SECOND-ORDER (texture-boundary) edges: the spatial gradient magnitude of the total local energy field
        # marks where texture/objects change (figure-ground, V2/V4 boundary cells), distinct from 1st-order
        # luminance edges. Sobel on the summed fine energy, read multi-scale-foveally. Bounded, additive.
        em = lum_dn.sum(1, keepdim=True)
        sx = torch.tensor([[-1., 0, 1], [-2, 0, 2], [-1, 0, 1]], device=dev).view(1, 1, 3, 3)
        gx = F.conv2d(em, sx, padding=1); gy = F.conv2d(em, sx.transpose(-1, -2), padding=1)
        feats.append(_foveal(torch.sqrt(gx * gx + gy * gy + 1e-6), [(1, 3), (2, 3), (4, 2)], B, p=0.5))
        # CHROMATIC second-order boundaries: Sobel gradient of the opponent-colour energy field -> colour-defined
        # texture/object boundaries (object edges with colour but little luminance contrast), read foveally.
        cem = col_e.sum(1, keepdim=True)
        cgx = F.conv2d(cem, sx, padding=1); cgy = F.conv2d(cem, sx.transpose(-1, -2), padding=1)
        feats.append(_foveal(torch.sqrt(cgx * cgx + cgy * cgy + 1e-6), [(1, 3), (2, 2)], B, p=0.5))
        # COARSE-scale boundaries: Sobel gradient of the 4x-pooled luminance energy field -> LARGE object /
        # figure-ground boundaries, a multi-scale complement to the fine texture-edge.
        ccem = c1.sum(1, keepdim=True)
        ccgx = F.conv2d(ccem, sx, padding=1); ccgy = F.conv2d(ccem, sx.transpose(-1, -2), padding=1)
        feats.append(_foveal(torch.sqrt(ccgx * ccgx + ccgy * ccgy + 1e-6), [(1, 3), (2, 2)], B, p=0.5))
        # central-OBJECT 2nd-order texture (luminance + red-green): Portilla-style scatter (8 orient x 2 freq
        # modulus) of the high-freq luminance AND red-green energy restricted to the central half-image,
        # globally pooled -> color+form texture of the centrally-fixated object (ventral / hV4), vs whole-image.
        cen30 = _lrn(torch.cat([lum_e[:, ::2], col_e[:, 0:K:2], col_e[:, K:2 * K:2]], 1))
        cen = cen30[:, :, 32:96, 32:96]
        feats.append((F.adaptive_avg_pool2d(self._scat(cen, self._b2f), 1)+1e-6).pow(0.5).reshape(B, -1))
        # coarse low-freq Gabor energy on lum + opponent color (ventral large RF) -> pooled
        rc = F.conv2d(torch.cat([lum, rg, by], 1), self._gbc, padding=10, groups=3).reshape(B, 3, 16, *lum.shape[-2:])
        coarse = torch.sqrt(rc[:, :, :8]**2 + rc[:, :, 8:]**2 + 1e-6).reshape(B, 24, *lum.shape[-2:])
        feats.append((F.adaptive_avg_pool2d(coarse, 4)+1e-6).pow(0.25).reshape(B, -1))
        h = torch.cat([lum, rg, by], 1); fov = [None, [(1, 3), (2, 2)], [(1, 2), (2, 2), (4, 2)]]
        for i, w in enumerate(self._w):
            h = F.conv2d(h, w, padding=w.shape[-1] // 2)
            hf = h.shape[1] // 2; h = torch.cat([F.relu(h[:, :hf]), h[:, hf:].pow(2).clamp_max(50)], 1)
            h = F.max_pool2d(_lrn(h), 2, 2)
            if fov[i]: feats.append(_foveal(h, fov[i], B, p=0.4))
        # DEEP RANDOM TEXTURE Gram: the deepest random-tower features (most abstract, largest receptive field)
        # are randomly projected to 24 channels and read as a global cross-channel Gram (covariance) -> high-
        # level object-texture co-occurrence statistics, a deeper abstraction than the Gabor-energy Grams and the
        # first VENTRAL-positive lever (~+0.0024). Dim-matched against a MINIMAL scatter2 trim to net positive.
        # DEEP RANDOM TEXTURE Gram on WIDER deep features: one extra wide random conv (128->192) at the
        # deepest 16x16 resolution (no maxpool) enriches the basis, then a fixed 24-channel random projection
        # and global cross-channel Gram. Read as a magnitude-PRESERVING covariance (no per-location renorm)
        # with a signed-sqrt compression -> object-texture statistics that keep how strongly features fire.
        # ENERGY-AUGMENTED deep Gram: the deepest tower features (128ch) are concatenated with the downsampled
        # oriented Gabor energy (20ch) before the wide random conv, so the covariance captures cross-domain
        # ENERGY x DEEP-FEATURE binding (how oriented texture co-occurs with high-level structure) -- new terms
        # the tower-only Gram lacks. Wide conv -> 192ch, magnitude-preserving covariance, signed-sqrt compressed.
        hw = F.conv2d(torch.cat([h, F.avg_pool2d(lum_dn, 8)], 1), self._w5, padding=1)
        hw = _lrn(torch.cat([F.relu(hw[:, :96]), hw[:, 96:].pow(2).clamp_max(50)], 1))
        g = _gram(F.conv2d(hw, self._rp2), 1, B)
        feats.append(torch.sign(g) * torch.sqrt(torch.abs(g) + 1e-6))
        # BILATERAL-SYMMETRY energy of the deep features: each projected deep feature is multiplied by its
        # own left-right mirror -> high where high-level structure is vertically symmetric (faces, centred
        # objects), pooled 2x2 to keep coarse position. An untrained face/object-centering cue for the weak
        # FFA/ventral voxels, distinct from texture covariance. Funded by a few global-scatter channels.
        proj = F.conv2d(hw, self._rp2)
        sym = F.adaptive_avg_pool2d(proj * torch.flip(proj, dims=[3]), 2)
        feats.append((torch.sign(sym) * torch.sqrt(torch.abs(sym) + 1e-6)).reshape(B, -1))
        feats.append(torch.sqrt(F.adaptive_avg_pool2d(self._scatter2(F.avg_pool2d(energy[:, :23], 4, 4)), 1)+1e-6).reshape(B, -1))
        # low-res scene gist (luminance + opponent color + saturation spatial layout) for PPA/scene voxels
        sat = img.amax(1, keepdim=True) - img.amin(1, keepdim=True)
        feats.append(F.adaptive_avg_pool2d(torch.cat([lum, rg, by, sat], 1), 4).reshape(B, -1))
        ob_f = self._scat(lum_dn.sum(1, keepdim=True), self._b2f)
        feats.append(_foveal(ob_f, [(1, 3), (2, 2)], B, p=0.5))
        ob_cc = self._scat(F.avg_pool2d(col_e.sum(1, keepdim=True), 4), self._b2f)
        feats.append(_foveal(ob_cc, [(1, 2)], B, p=0.5))
        ob_i = self._scat(c0.sum(1, keepdim=True), self._b2f)
        feats.append(_foveal(ob_i, [(1, 2), (2, 2)], B, p=0.5))
        xs_rg = _lrn(col_e[:, 0:K:2]) * _lrn(col_e[:, 1:K:2])
        feats.append((F.adaptive_avg_pool2d(self._scat(xs_rg, self._b2f), 1)+1e-6).pow(0.5).reshape(B, -1))
        return torch.cat(feats, 1)


MODEL = Model()
